-- Postings and one ordered student application per round.
DO $$ BEGIN CREATE TYPE round_phase AS ENUM ('ranking_open','ranking_locked','shortlisting','shortlist_locked','interviewing','company_ranking','company_locked','matched','revealed'); EXCEPTION WHEN duplicate_object THEN NULL; END $$;
CREATE TABLE IF NOT EXISTS rounds (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), label text NOT NULL, phase round_phase NOT NULL DEFAULT 'ranking_open', ranking_opens_at timestamptz, ranking_locks_at timestamptz, shortlist_locks_at timestamptz, company_locks_at timestamptz, reveal_at timestamptz, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS postings (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), company_id uuid NOT NULL REFERENCES companies(id) ON DELETE CASCADE, round_id uuid NOT NULL REFERENCES rounds(id) ON DELETE CASCADE, title text NOT NULL, required_department text NOT NULL DEFAULT '', required_skills text[] NOT NULL DEFAULT '{}', capacity integer NOT NULL DEFAULT 1 CHECK(capacity BETWEEN 1 AND 10), created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS student_rankings (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), student_id uuid NOT NULL REFERENCES students(id) ON DELETE CASCADE, round_id uuid NOT NULL REFERENCES rounds(id) ON DELETE CASCADE, ordered_posting_ids uuid[] NOT NULL DEFAULT '{}', locked_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(student_id,round_id));
CREATE INDEX IF NOT EXISTS idx_postings_round ON postings(round_id);
CREATE INDEX IF NOT EXISTS idx_student_rankings_round ON student_rankings(round_id);
ALTER TABLE rounds ENABLE ROW LEVEL SECURITY; ALTER TABLE postings ENABLE ROW LEVEL SECURITY; ALTER TABLE student_rankings ENABLE ROW LEVEL SECURITY;
